#!/usr/bin/env node
// Builds this repository from the open tables generated by the czechdatasets.com web build.
//
//   node scripts/build.mjs <path to the czechdatasets repo>/web
//
// Reads  <web>/data/otevrena.json (table metadata) and <web>/public/open/* (CSV, Markdown).
// Writes README.md, LICENSE.md, datapackage.json, data/*.csv, docs/en/*.md, docs/cs/*.md
// and upload-ready folders dist/huggingface and dist/kaggle (not committed).
import { cpSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const WEB = resolve(process.argv[2] ?? '');
const KOREN = resolve(import.meta.dirname, '..');
const SITE = 'https://czechdatasets.com';
const REPO = 'sth3no/czech-open-data';
const RAW = `https://raw.githubusercontent.com/${REPO}/main`;

const { tabulky } = JSON.parse(readFileSync(join(WEB, 'data/otevrena.json'), 'utf8'));
const cti = (cesta) => readFileSync(join(WEB, 'public/open', cesta), 'utf8');
const cislo = (n, jazyk = 'en-US') => n.toLocaleString(jazyk);
const stav = (md, navesti) => (md.match(new RegExp(`\\*\\*${navesti}:\\*\\* (.+)`)) ?? [])[1] ?? '';
const odkaz = (text, url) => (url ? `[${text}](${url})` : text);
const bunka = (s) => String(s).replaceAll('|', '\\|').replaceAll('\n', ' ');

for (const d of ['data', 'docs', 'dist']) rmSync(join(KOREN, d), { recursive: true, force: true });
for (const d of ['data', 'docs/en', 'docs/cs', 'dist/huggingface/data', 'dist/kaggle']) mkdirSync(join(KOREN, d), { recursive: true });

const T = tabulky.map((t) => {
  const en = cti(`en/${t.slug}.md`), cs = cti(`${t.slug}.md`);
  cpSync(join(WEB, 'public/open', `${t.slug}.csv`), join(KOREN, 'data', `${t.slug}.csv`));
  writeFileSync(join(KOREN, 'docs/en', `${t.slug}.md`), en);
  writeFileSync(join(KOREN, 'docs/cs', `${t.slug}.md`), cs);
  return { ...t, stavEn: stav(en, 'Data as of'), stavCs: stav(cs, 'Stav dat') };
});
const radku = T.reduce((a, t) => a + t.radku, 0);

// Tables grouped by the dataset they come from, in the order of the website.
const skupiny = [];
for (const t of T) {
  let s = skupiny.find((x) => x.sada === t.sada);
  if (!s) skupiny.push((s = { sada: t.sada, en: t.en.sada, cs: t.cs.sada, tabulky: [] }));
  s.tabulky.push(t);
}

const prehled = (j) => skupiny.map((s) => {
  const hlavicka = j === 'en'
    ? '| Table | Rows | Data as of | Source | Licence | Files |\n| --- | ---: | --- | --- | --- | --- |'
    : '| Tabulka | Řádků | Stav dat | Zdroj | Licence | Soubory |\n| --- | ---: | --- | --- | --- | --- |';
  const radky = s.tabulky.map((t) => {
    const stranka = j === 'en' ? `${SITE}/en/otevrena-data/${t.slug}` : `${SITE}/otevrena-data/${t.slug}`;
    return `| ${odkaz(bunka(t.nazev[j]), stranka)} | ${cislo(t.radku, j === 'en' ? 'en-US' : 'cs-CZ')} | ${j === 'en' ? t.stavEn : t.stavCs} | ${odkaz(bunka(t.zdroj[j]), t.zdroj_url)} | ${odkaz(bunka(t[j].licence), t.licenceUrl)} | [CSV](data/${t.slug}.csv) · [${j === 'en' ? 'columns' : 'sloupce'}](docs/${j}/${t.slug}.md) |`;
  });
  const sada = s.sada === 'zdarma' ? '' : (j === 'en' ? ` ([full dataset](${SITE}/en/data/${s.sada}))` : ` ([celá sada](${SITE}/data/${s.sada}))`);
  return `### ${s[j]}${sada}\n\n${hlavicka}\n${radky.join('\n')}`;
}).join('\n\n');

const uvodEn = `${T.length} open tables about the Czech Republic, built from official open data: municipalities, postcodes and territorial units (RÚIAN), companies, data boxes, schools, healthcare providers, pharmacies, medicines, election results, wages, population and municipal statistics. ${cislo(radku)} rows in total, as UTF-8 CSV with documented columns.`;

const telo = `# Czech open data tables

${uvodEn}

The tables are published and kept up to date at **[czechdatasets.com/en/otevrena-data](${SITE}/en/otevrena-data)** (Czech: [czechdatasets.com/otevrena-data](${SITE}/otevrena-data)). This repository is a mirror for people and tools that prefer Git, a raw file URL or a data package.

- **Format:** UTF-8 CSV, comma separated, header row, \`.\` as decimal point. Column names are Czech without diacritics; every column is described in English and Czech in \`docs/\`.
- **Sources:** Czech public authorities (ČÚZK, Czech Statistical Office, Digital and Information Agency, Ministry of Labour, Ministry of Education, SÚKL, ÚZIS, Czech National Bank and others). Each table names its source and the date the data refers to.
- **Machine-readable description:** [\`datapackage.json\`](datapackage.json) (Frictionless Data Package) and ${SITE}/open/index.json.
- **Free to use:** no registration and no API key. Licences differ by table, see [LICENSE.md](LICENSE.md).

## Tables

${prehled('en')}

## Using the data

Every file has a stable address in this repository and on the website:

\`\`\`
${RAW}/data/psc.csv
${SITE}/open/psc.csv
${SITE}/open/psc.json
\`\`\`

Python:

\`\`\`python
import pandas as pd
obce = pd.read_csv("${RAW}/data/obce-cr.csv", dtype={"obec_kod": str})
\`\`\`

DuckDB:

\`\`\`sql
SELECT kraj, count(*) AS obci FROM '${RAW}/data/obce-cr.csv' GROUP BY kraj ORDER BY obci DESC;
\`\`\`

## How to cite

Cite the original source named on the table together with "processed by czechdatasets.com" and link the table page, for example:

> Source: Czech Statistical Office; processed by czechdatasets.com, ${SITE}/en/otevrena-data/obyvatelstvo-obci-2026

The exact wording for each table is in its file in \`docs/en/\` under "How to cite".

## Full datasets

The open tables are aggregates, code lists and latest snapshots. The complete datasets behind them (every address, parcel, company, vacancy or election result, with history) are available as one-off downloads at [czechdatasets.com](${SITE}/en). Sample files of each dataset are free at ${SITE}/en/data/zdarma.

## Česky

${T.length} otevřených tabulek o České republice z oficiálních otevřených dat: obce, PSČ a územní členění (RÚIAN), firmy, datové schránky, školy, poskytovatelé zdravotní péče, lékárny, léčiva, volby, mzdy, obyvatelstvo a ukazatele obcí. Celkem ${cislo(radku, 'cs-CZ')} řádků v CSV (UTF-8, oddělovač čárka, záhlaví v prvním řádku). Tabulky vycházejí na **[czechdatasets.com/otevrena-data](${SITE}/otevrena-data)**, tento repozitář je jejich zrcadlo. Popis sloupců česky je ve složce \`docs/cs/\`, licence jednotlivých tabulek v [LICENSE.md](LICENSE.md).

${prehled('cs')}
`;

writeFileSync(join(KOREN, 'README.md'), telo);

// ---------- licences ----------
const licence = `# Licences

The tables come from different Czech public authorities and keep the licence or terms of use of their source. There is no single licence for the whole repository. Attribution to the original source is required wherever the licence says so; please also keep "processed by czechdatasets.com".

| File | Source | Licence or terms |
| --- | --- | --- |
${T.map((t) => `| [data/${t.slug}.csv](data/${t.slug}.csv) | ${odkaz(bunka(t.zdroj.en), t.zdroj_url)} | ${odkaz(bunka(t.en.licence), t.licenceUrl)} |`).join('\n')}

The two Czech National Bank tables carry the bank's values without alteration, as its terms require; credit them as "Source: ČNB (Czech National Bank)". The descriptions, column documentation and the build script in this repository are released under [CC BY 4.0](https://creativecommons.org/licenses/by/4.0/) by czechdatasets.com.
`;
writeFileSync(join(KOREN, 'LICENSE.md'), licence);

// ---------- Frictionless Data Package ----------
const pole = (t) => t.sloupce.map((s, i) => ({ name: s.nazev, type: t.typy?.[i] === 'cislo' ? 'number' : 'string', description: s.popis.en }));
const balik = {
  name: 'czech-open-data',
  title: 'Czech open data tables',
  description: uvodEn,
  homepage: `${SITE}/en/otevrena-data`,
  keywords: ['Czech Republic', 'Czechia', 'open data', 'RÚIAN', 'municipalities', 'postcodes', 'companies', 'elections', 'wages', 'population'],
  contributors: [{ title: 'czechdatasets.com', path: SITE, role: 'publisher' }],
  resources: T.map((t) => ({
    name: t.slug,
    path: `data/${t.slug}.csv`,
    title: t.nazev.en,
    description: t.popis.en,
    format: 'csv', mediatype: 'text/csv', encoding: 'utf-8',
    bytes: t.bajtu,
    homepage: `${SITE}/en/otevrena-data/${t.slug}`,
    sources: [{ title: t.zdroj.en, ...(t.zdroj_url ? { path: t.zdroj_url } : {}) }],
    licenses: [{ title: t.en.licence, ...(t.licenceUrl ? { path: t.licenceUrl } : {}) }],
    schema: { fields: pole(t) },
  })),
};
writeFileSync(join(KOREN, 'datapackage.json'), JSON.stringify(balik, null, 2) + '\n');

// ---------- Hugging Face: dataset card with one config per table ----------
const velikost = radku < 1e4 ? '1K<n<10K' : radku < 1e5 ? '10K<n<100K' : '100K<n<1M';
const karta = `---
pretty_name: Czech open data tables
language:
- cs
- en
license: other
license_name: mixed-open-licences
license_link: https://github.com/${REPO}/blob/main/LICENSE.md
size_categories:
- ${velikost}
tags:
- czech-republic
- czechia
- open-data
- tabular
- geography
- statistics
- ruian
- municipalities
- postcodes
- elections
configs:
${T.map((t) => `- config_name: ${t.slug}\n  data_files: data/${t.slug}.csv`).join('\n')}
---

${telo.replaceAll('](data/', `](https://github.com/${REPO}/blob/main/data/`).replaceAll('](docs/', `](https://github.com/${REPO}/blob/main/docs/`).replaceAll('](LICENSE.md)', `](https://github.com/${REPO}/blob/main/LICENSE.md)`).replaceAll('](datapackage.json)', `](https://github.com/${REPO}/blob/main/datapackage.json)`)}`;
writeFileSync(join(KOREN, 'dist/huggingface/README.md'), karta);
cpSync(join(KOREN, 'data'), join(KOREN, 'dist/huggingface/data'), { recursive: true });

// ---------- Kaggle: flat folder with dataset-metadata.json ----------
cpSync(join(KOREN, 'data'), join(KOREN, 'dist/kaggle'), { recursive: true });
writeFileSync(join(KOREN, 'dist/kaggle/dataset-metadata.json'), JSON.stringify({
  title: 'Czech open data tables',
  id: 'KAGGLE_USERNAME/czech-open-data-tables',
  subtitle: 'Municipalities, postcodes, companies, elections, wages and more as CSV',
  description: telo.replace(/^# .*\n\n/, '').replaceAll('](data/', `](https://github.com/${REPO}/blob/main/data/`).replaceAll('](docs/', `](https://github.com/${REPO}/blob/main/docs/`).replaceAll('](LICENSE.md)', `](https://github.com/${REPO}/blob/main/LICENSE.md)`).replaceAll('](datapackage.json)', `](https://github.com/${REPO}/blob/main/datapackage.json)`),
  licenses: [{ name: 'other' }],
  keywords: ['europe', 'geography', 'government', 'business', 'demographics'],
  resources: T.map((t) => ({ path: `${t.slug}.csv`, description: `${t.nazev.en}. ${t.popis.en} Source: ${t.zdroj.en}. Licence: ${t.en.licence}.`, schema: { fields: pole(t) } })),
}, null, 2) + '\n');

console.log(`${T.length} tables, ${cislo(radku)} rows; README.md, LICENSE.md, datapackage.json, data/, docs/, dist/`);
